// Exact minimum distance of the stabilizer code 32-9-6 (data/codes/32-9-6.json):
// magma -b magma/32-9-6.m
SetQuitOnError(true); SetColumns(0);
SetVerbose("Code", 1);
ma, mi, pa := GetVersion(); printf "Magma V%o.%o-%o\n", ma, mi, pa;
n := 32;
F2 := GF(2);
rows := [];
v := [F2!0 : i in [1..2*n]]; for q in [0, 3, 12, 31] do v[q+1] := 1; end for; for q in [15, 18, 20, 25] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [0, 1, 13, 28] do v[q+1] := 1; end for; for q in [14, 17, 23, 24] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [1, 2, 14, 29] do v[q+1] := 1; end for; for q in [13, 16, 22, 27] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [2, 3, 15, 30] do v[q+1] := 1; end for; for q in [12, 19, 21, 26] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [0, 4, 7, 19] do v[q+1] := 1; end for; for q in [11, 16, 21, 30] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [1, 4, 5, 16] do v[q+1] := 1; end for; for q in [10, 19, 20, 29] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [2, 5, 6, 17] do v[q+1] := 1; end for; for q in [9, 18, 23, 28] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [3, 6, 7, 18] do v[q+1] := 1; end for; for q in [8, 17, 22, 31] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [4, 8, 11, 23] do v[q+1] := 1; end for; for q in [7, 17, 26, 28] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [5, 8, 9, 20] do v[q+1] := 1; end for; for q in [6, 16, 25, 31] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [6, 9, 10, 21] do v[q+1] := 1; end for; for q in [5, 19, 24, 30] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [7, 10, 11, 22] do v[q+1] := 1; end for; for q in [4, 18, 27, 29] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [8, 12, 15, 27] do v[q+1] := 1; end for; for q in [3, 22, 24, 29] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [9, 12, 13, 24] do v[q+1] := 1; end for; for q in [2, 21, 27, 28] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [10, 13, 14, 25] do v[q+1] := 1; end for; for q in [1, 20, 26, 31] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [11, 14, 15, 26] do v[q+1] := 1; end for; for q in [0, 23, 25, 30] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [15, 16, 19, 28] do v[q+1] := 1; end for; for q in [2, 4, 9, 31] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [12, 16, 17, 29] do v[q+1] := 1; end for; for q in [1, 7, 8, 30] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [13, 17, 18, 30] do v[q+1] := 1; end for; for q in [0, 6, 11, 29] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [14, 18, 19, 31] do v[q+1] := 1; end for; for q in [3, 5, 10, 28] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [3, 16, 20, 23] do v[q+1] := 1; end for; for q in [0, 5, 14, 27] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [0, 17, 20, 21] do v[q+1] := 1; end for; for q in [3, 4, 13, 26] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [1, 18, 21, 22] do v[q+1] := 1; end for; for q in [2, 7, 12, 25] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [2, 19, 22, 23] do v[q+1] := 1; end for; for q in [1, 6, 15, 24] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [7, 20, 24, 27] do v[q+1] := 1; end for; for q in [1, 10, 12, 23] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [4, 21, 24, 25] do v[q+1] := 1; end for; for q in [0, 9, 15, 22] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [5, 22, 25, 26] do v[q+1] := 1; end for; for q in [3, 8, 14, 21] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [6, 23, 26, 27] do v[q+1] := 1; end for; for q in [2, 11, 13, 20] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [11, 24, 28, 31] do v[q+1] := 1; end for; for q in [6, 8, 13, 19] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [8, 25, 28, 29] do v[q+1] := 1; end for; for q in [5, 11, 12, 18] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [9, 26, 29, 30] do v[q+1] := 1; end for; for q in [4, 10, 15, 17] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [10, 27, 30, 31] do v[q+1] := 1; end for; for q in [7, 9, 14, 16] do v[n+q+1] := 1; end for; Append(~rows, v);
M := Matrix(F2, rows);
Q := QuantumCode(M : ExtendedFormat := true);
print "code:", Length(Q), Dimension(Q);
assert Length(Q) eq 32 and Dimension(Q) eq 9;
t := Cputime(); d := MinimumDistance(Q); print "MinimumDistance:", d, "cputime:", Cputime(t);
exit;
